(function(){
'use strict';

const TEAMS_URL='ffws-br-2026-s2/teams.json?v=20260728-local-logos-v2';
const LOCAL_TEAM_LOGOS={AFROGAMES:'afg.webp',CPTVOX:'cpt vox.webp',SXTET:'sx tet.webp'};
const CHANNEL_URL='https://www.youtube.com/@ffesportsbr';
const SEASON_START='2026-08-01';
const SEASON_END='2026-10-10';
const START_HOUR=13;
const LIVE_WINDOW_MS=6*60*60*1000;
let teams=[];
let state={
  roundLabel:'Próxima rodada',
  restingTeams:Array.isArray(window.FFWS_BR_HOME_RESTING_TEAMS)?window.FFWS_BR_HOME_RESTING_TEAMS:[]
};

function normalize(value){
  return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'').toUpperCase();
}
function esc(value){
  return String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;');
}
function pad(value){return String(Math.max(0,Number(value)||0)).padStart(2,'0')}
function setText(id,value){const el=document.getElementById(id);if(el)el.textContent=value}
function formatDate(timestamp){
  return new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',weekday:'long',day:'2-digit',month:'long',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(timestamp)).replace(/^./,letter=>letter.toUpperCase())+' (BRT)';
}
function schedule(){
  const dates=[];
  const start=new Date(SEASON_START+'T00:00:00Z');
  const end=new Date(SEASON_END+'T00:00:00Z');
  for(let current=new Date(start);current<=end;current.setUTCDate(current.getUTCDate()+1)){
    const day=current.getUTCDay();
    if(day!==0&&day!==6)continue;
    const iso=current.toISOString().slice(0,10);
    dates.push(Date.parse(`${iso}T${String(START_HOUR).padStart(2,'0')}:00:00-03:00`));
  }
  return dates;
}
const broadcasts=schedule();

function updateTimer(){
  const card=document.getElementById('home-s2-broadcast');
  if(!card)return;
  const now=Date.now();
  const liveStart=broadcasts.find(start=>now>=start&&now<start+LIVE_WINDOW_MS);
  const next=broadcasts.find(start=>start>now);
  const clock=document.getElementById('home-s2-broadcast-clock');
  const livePill=document.getElementById('home-s2-live-pill');
  const watch=document.getElementById('home-s2-watch');
  if(watch)watch.href=CHANNEL_URL;

  if(liveStart){
    card.classList.add('is-live');
    if(clock)clock.hidden=true;
    if(livePill)livePill.hidden=false;
    setText('home-s2-broadcast-kicker','FFWS BRASIL 2026 S2 • TRANSMISSÃO OFICIAL');
    setText('home-s2-broadcast-title','AO VIVO AGORA');
    setText('home-s2-broadcast-date',formatDate(liveStart));
    if(watch)watch.textContent='AO VIVO AGORA →';
    return;
  }

  card.classList.remove('is-live');
  if(clock)clock.hidden=false;
  if(livePill)livePill.hidden=true;
  if(!next){
    setText('home-s2-broadcast-kicker','FFWS BRASIL 2026 S2');
    setText('home-s2-broadcast-title','TEMPORADA ENCERRADA');
    setText('home-s2-broadcast-date','Transmissões realizadas de 1º de agosto a 10 de outubro de 2026');
    setText('home-s2-days','00');setText('home-s2-hours','00');setText('home-s2-minutes','00');
    if(watch)watch.textContent='VER CANAL →';
    return;
  }

  const remaining=Math.max(0,next-now);
  const days=Math.floor(remaining/86400000);
  const hours=Math.floor((remaining%86400000)/3600000);
  const minutes=Math.floor((remaining%3600000)/60000);
  setText('home-s2-broadcast-kicker','FFWS BRASIL 2026 S2');
  setText('home-s2-broadcast-title','PRÓXIMA TRANSMISSÃO');
  setText('home-s2-broadcast-date',formatDate(next));
  setText('home-s2-days',pad(days));
  setText('home-s2-hours',pad(hours));
  setText('home-s2-minutes',pad(minutes));
  if(watch)watch.textContent='VER CANAL →';
}

function resolveLogo(team){
  const local=LOCAL_TEAM_LOGOS[normalize(team&&team.name)];
  if(local)return local;
  if(team.logo&&team.logo!=='escudo.webp')return team.logo;
  if(typeof window.getTeamLogoByAliases==='function'){
    const resolved=window.getTeamLogoByAliases(team.name);
    if(resolved&&resolved!=='escudo.webp')return resolved;
  }
  if(typeof window.logos==='object'&&window.logos){
    const key=Object.keys(window.logos).find(name=>normalize(name)===normalize(team.name));
    if(key&&window.logos[key])return window.logos[key];
  }
  return 'escudo.webp';
}
function openTeam(name){
  if(typeof window.openCurrentSeasonTeam==='function'){
    window.openCurrentSeasonTeam(name);
    return;
  }
  window.location.href='equipe.html?time='+encodeURIComponent(name);
}
function renderTeams(){
  const root=document.getElementById('home-s2-team-grid');
  if(!root)return;
  const resting=new Set((state.restingTeams||[]).map(normalize));
  root.innerHTML=teams.map(team=>{
    const isResting=resting.has(normalize(team.name));
    return `<button type="button" class="home-s2-team${isResting?' is-resting':''}" data-home-s2-team="${esc(team.name)}" aria-label="${esc(team.name)}${isResting?' — descansa nesta rodada':''}">
      <img decoding="async" loading="lazy" src="${esc(resolveLogo(team))}" alt="${esc(team.name)}" onerror="this.onerror=null;this.src='escudo.webp'">
      <strong title="${esc(team.name)}">${esc(team.abbreviation||team.name)}</strong>
    </button>`;
  }).join('');
  root.querySelectorAll('[data-home-s2-team]').forEach(button=>button.addEventListener('click',()=>openTeam(button.getAttribute('data-home-s2-team'))));
  const note=document.getElementById('home-s2-resting-note');
  if(note)note.hidden=resting.size===0;
  setText('home-s2-round-label',state.roundLabel||'Próxima rodada');
}
async function loadTeams(){
  try{
    const response=await fetch(TEAMS_URL,{cache:'default'});
    if(!response.ok)throw new Error(`HTTP ${response.status}`);
    const payload=await response.json();
    teams=Array.isArray(payload.teams)?payload.teams:[];
    renderTeams();
    if(typeof window.loadTeamLogos==='function'){
      Promise.resolve(window.loadTeamLogos()).then(()=>renderTeams()).catch(()=>{});
    }else setTimeout(renderTeams,1800);
  }catch(error){
    const root=document.getElementById('home-s2-team-grid');
    if(root)root.innerHTML='<div class="home-s2-team-loading">Não foi possível carregar as equipes agora.</div>';
    console.error('[Home FFWS S2] Equipes:',error);
  }
}

window.setHomeRestingTeams=function(restingTeams,roundLabel){
  state.restingTeams=Array.isArray(restingTeams)?restingTeams:[];
  if(roundLabel)state.roundLabel=String(roundLabel);
  renderTeams();
};
window.setHomeFFWSS2Round=function(config){
  const next=config&&typeof config==='object'?config:{};
  state.restingTeams=Array.isArray(next.restingTeams)?next.restingTeams:state.restingTeams;
  state.roundLabel=next.roundLabel||next.label||state.roundLabel;
  renderTeams();
};

function boot(){
  updateTimer();
  loadTeams();
  window.setInterval(updateTimer,30000);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
